WITH supplier_totals AS (SELECT supplier_id, SUM(CASE WHEN brand = 'Stark' THEN 1 ELSE 0 END) AS stark_count, SUM(CASE WHEN category = 'Grocery' THEN cost ELSE 0 END) AS grocery_cost FROM products GROUP BY supplier_id) SELECT s.id, s.country, s.supplier_name, st.stark_count, st.grocery_cost FROM suppliers s JOIN supplier_totals st ON s.id = st.supplier_id WHERE st.grocery_cost >= 53;
